#!/usr/bin/env python3
"""ES JC-ENGAGE-1012 - run in Cloud Shell from the live functions folder.
Patches main.py / lib/emails.py / packages json IN PLACE (backups *.pre-engage1012.bak),
compiles, then prints the deploy commands.
Also applies JC-ES-NEXT-1012 (welcome timeline + wedding_website) in the same run. Idempotent: skips files already patched."""
import io, os, sys, json, py_compile, shutil

EMAILS_BLOCK = '# ============================================================ milestones ==\n# JC-ES-ENGAGE-1012: the studio\'s planning rhythm between signing and the\n# wedding. Written for ES\'s editorial voice (not the Atavia timeline emails):\n#   planning_roadmap  3 days after signing   - the five milestones, in order\n#   studio_note       every 6 weeks          - one question for the couple, while > 45 days out\n#   final_details     10 days before         - confirm the day, reply required\n# Driven by _send_milestones in main.py.\n\n_ES_WRAP = (\'<div style="font-family:Georgia,serif;color:#2B2B2B;max-width:560px;margin:0 auto">\'\n            \'<h1 style="font-weight:normal;letter-spacing:2px">ELIZABETH SCOTT WEDDINGS</h1>\'\n            \'{body}\' + _SIGNOFF + \'</div>\')\n\n\ndef _es_first(booking):\n    return booking["client_names"].split("&")[0].strip().split()[0]\n\n\ndef planning_roadmap(api_key, booking, q_link=None):\n    first = _es_first(booking)\n    plan = booking.get("payment_option")\n    money = ("Your collection is paid in full. There is nothing further to pay."\n             if plan != "standard" else\n             f"Your balance is scheduled for <b>{booking.get(\'balance_due_date\',\'\')}</b>, fourteen days "\n             "before the wedding, to the card you reserved with, exactly as your agreement sets out.")\n    body = f"""\n      <p>Hi {first},</p>\n      <p>Your agreement is signed and <b>{booking.get(\'event_date\',\'\')}</b> is yours. From here we\n      work in five milestones, and we will come to you at each one. You never need to chase us.</p>\n      <ol style="line-height:1.8;padding-left:20px">\n        <li><b>Now.</b> {money}</li>\n        <li><b>At your pace.</b> Your Wedding Day Questionnaire: venues, timeline, the people who\n        matter. Ten minutes, editable until two weeks out.</li>\n        <li><b>Every six weeks.</b> A short note from the studio with one question that shapes how we\n        film your day. Reply or ignore; both are fine.</li>\n        <li><b>Ten days out.</b> Final details: we send back everything we have and ask you to confirm\n        it in one reply.</li>\n        <li><b>After.</b> Your film, delivered as set out in your agreement, with a note from the\n        editor on what we loved.</li>\n      </ol>\n      {_btn(q_link, "BEGIN YOUR QUESTIONNAIRE") if q_link else ""}\n      <p>Questions at any point: reply to this email. It reaches the studio directly and is answered\n      by a person, usually the same day.</p>"""\n    return _send(api_key, booking["email"],\n                 f"Your planning roadmap — {booking.get(\'event_date\',\'\')}", _ES_WRAP.format(body=body))\n\n\n_STUDIO_QUESTIONS = [\n    ("Who is the one person you most want to see react when you walk in?",\n     "Tell us who, and we will have a camera on them."),\n    ("Are you writing your own vows, or reading letters to each other beforehand?",\n     "Either way, we record the audio separately so every word survives."),\n    ("Is there a song, a place, or an object that will mean something only to the two of you?",\n     "These are the details that make a film yours and not a template."),\n    ("Would you rather we are invisible, or part of the room?",\n     "Some couples want us never noticed; others like a little direction. Both are good answers."),\n    ("What is the one moment you are nervous about?",\n     "Often it is the one we can make easiest, if we know in advance."),\n]\n\n\ndef studio_note(api_key, booking, q_link, n, days_to_event, q_done):\n    first = _es_first(booking)\n    q, why = _STUDIO_QUESTIONS[n % len(_STUDIO_QUESTIONS)]\n    weeks = max(1, round(days_to_event / 7))\n    qline = ("" if q_done else\n             f\'<p style="font-size:13px;color:#6B6B6B">Your questionnaire is still open: \'\n             f\'<a href="{q_link}" style="color:{ACCENT}">complete it when you have ten minutes</a>.</p>\')\n    body = f"""\n      <p>Hi {first},</p>\n      <p>A note from the studio, {weeks} weeks out from {booking.get(\'event_date\',\'\')}.\n      Everything is on track and nothing is required of you.</p>\n      <p style="font-size:18px;line-height:1.5;margin:22px 0 6px"><i>{q}</i></p>\n      <p>{why} Reply with a line or two if you like.</p>\n      {qline}\n      <p>And if anything has changed since we last spoke, that is the other reason to reply.</p>"""\n    return _send(api_key, booking["email"],\n                 f"A note from the studio — {booking.get(\'event_date\',\'\')}", _ES_WRAP.format(body=body))\n\n\ndef final_details(api_key, booking, q_link, q_done):\n    first = _es_first(booking)\n    rows = ""\n    for label, key in (("Ceremony", "ceremony_venue"), ("Reception", "reception_venue"),\n                       ("Coverage begins", "start_time"), ("Coverage ends", "end_time"),\n                       ("Collection", "package_name")):\n        v = booking.get(key)\n        if v:\n            rows += (f\'<tr><td style="padding:4px 14px 4px 0;color:#6B6B6B;font-size:12px">{label}</td>\'\n                     f\'<td style="padding:4px 0;font-size:13px">{v}</td></tr>\')\n    table = f\'<table style="width:100%;border-collapse:collapse;margin:16px 0">{rows}</table>\' if rows else ""\n    missing = ("" if q_done else\n               f\'<p><b>We do not yet have your questionnaire.</b> Please <a href="{q_link}" \'\n               f\'style="color:{ACCENT}">complete it now</a>, or simply reply with your timeline and \'\n               \'the names that matter, and we will build the plan from that.</p>\')\n    body = f"""\n      <p>Hi {first},</p>\n      <p>Ten days out. This is everything we are working from for <b>{booking.get(\'event_date\',\'\')}</b>:</p>\n      {table}\n      {missing}\n      <p><b>Please reply to this email with one word, "confirmed", or with any corrections.</b>\n      We lock the plan and assign the crew on your reply.</p>\n      <p>Thank you for trusting us with this.</p>"""\n    return _send(api_key, booking["email"],\n                 f"Final details, please confirm — {booking.get(\'event_date\',\'\')}", _ES_WRAP.format(body=body))\n'
SWEEP_BLOCK = '# ========================================================== milestones ==\n# JC-ES-ENGAGE-1012: see lib/emails.py. Stamps on the booking doc:\n#   roadmap_sent_at, studio_note_count, studio_note_last_at, final_details_sent_at\nMILESTONE_ROADMAP_AFTER_DAYS = 3      # planning_roadmap: days after the retainer is paid\nMILESTONE_ROADMAP_MAX_DAYS = 21       # ...but never to a couple who booked longer ago than this\nMILESTONE_NOTE_EVERY_DAYS = 42        # studio_note cadence (six weeks)\nMILESTONE_NOTE_MIN_DAYS_OUT = 45      # no notes inside this window (questionnaire reminders take over)\nMILESTONE_FINAL_DAYS = 10             # final_details\nMILESTONE_QUIET_AROUND_BALANCE_DAYS = 2\n\n\ndef _send_milestones(db, now):\n    """The studio\'s planning rhythm between signing and the wedding. At most\n    one email per booking per run; every send is stamped. Non-fatal."""\n    from google.cloud.firestore_v1.base_query import FieldFilter\n    try:\n        snaps = (db.collection("bookings")\n                   .where(filter=FieldFilter("status", "==", "confirmed")).get())\n    except Exception as e:\n        print(f"milestones query failed: {e}"); return\n    today = now.date()\n    counts = {"roadmap": 0, "note": 0, "final": 0}\n    for snap in snaps:\n        b = snap.to_dict() or {}\n        if b.get("test_mode") or not b.get("email") or "@" not in str(b.get("email")):\n            continue\n        try:\n            ev = datetime.strptime(b.get("event_date_raw", ""), "%Y-%m-%d").date()\n        except ValueError:\n            continue\n        days = (ev - today).days\n        if days < 0:\n            continue\n        paid = b.get("deposit_paid_at") or b.get("created_at")\n        if not paid:\n            continue\n        if hasattr(paid, "tzinfo") and paid.tzinfo is None:\n            paid = paid.replace(tzinfo=timezone.utc)\n        since_paid = (now - paid).days\n        q_done = bool(b.get("questionnaire_submitted_at"))\n        link = _q_link(b["booking_id"], GRATUITY_SECRET.value)\n        bd = b.get("balance_due_at")\n        near_balance = False\n        if bd is not None and not b.get("balance_paid_at"):\n            if hasattr(bd, "tzinfo") and bd.tzinfo is None:\n                bd = bd.replace(tzinfo=timezone.utc)\n            near_balance = abs((bd - now).days) <= MILESTONE_QUIET_AROUND_BALANCE_DAYS\n        try:\n            if days <= MILESTONE_FINAL_DAYS and days >= 3 and not b.get("final_details_sent_at"):\n                emails.final_details(RESEND_API_KEY.value, b, link, q_done)\n                snap.reference.update({"final_details_sent_at": firestore.SERVER_TIMESTAMP})\n                counts["final"] += 1\n                continue\n            if (not b.get("roadmap_sent_at")\n                    and MILESTONE_ROADMAP_AFTER_DAYS <= since_paid <= MILESTONE_ROADMAP_MAX_DAYS\n                    and days > MILESTONE_FINAL_DAYS):\n                bdd = b.get("balance_due_at")\n                b["balance_due_date"] = bdd.strftime("%B %d, %Y") if hasattr(bdd, "strftime") else ""\n                emails.planning_roadmap(RESEND_API_KEY.value, b, q_link=link)\n                snap.reference.update({"roadmap_sent_at": firestore.SERVER_TIMESTAMP})\n                counts["roadmap"] += 1\n                continue\n            if ((b.get("roadmap_sent_at") or since_paid > MILESTONE_ROADMAP_MAX_DAYS)\n                    and days > MILESTONE_NOTE_MIN_DAYS_OUT and not near_balance):\n                last = b.get("studio_note_last_at") or b.get("roadmap_sent_at") or paid\n                if hasattr(last, "tzinfo") and last.tzinfo is None:\n                    last = last.replace(tzinfo=timezone.utc)\n                if (now - last).days >= MILESTONE_NOTE_EVERY_DAYS:\n                    n = int(b.get("studio_note_count") or 0)\n                    emails.studio_note(RESEND_API_KEY.value, b, link, n, days, q_done)\n                    snap.reference.update({"studio_note_last_at": firestore.SERVER_TIMESTAMP,\n                                           "studio_note_count": n + 1})\n                    counts["note"] += 1\n        except Exception as e:\n            print(f"milestone failed {b.get(\'booking_id\', snap.id)}: {e}")\n    print(f"milestones: {counts}")\n\n\n'
EDITS = [('    if days_to_event <= RULES.get("rush_days", 14):\n        option = "pif"                      # rush dates are PIF-only', '    if days_to_event <= RULES.get("rush_days", 14):\n        option = "pif"                      # rush dates are PIF-only\n    if RULES.get("pif_required_within_days", 0) and days_to_event <= RULES["pif_required_within_days"]:\n        option = "pif"                      # JC-ES-ENGAGE-1012: close-in weddings are paid in full'), ('        if event_dt.date() <= datetime.now().date():\n            return _res({"error": "event date must be in the future"}, 400)', '        if event_dt.date() <= datetime.now().date():\n            return _res({"error": "event date must be in the future"}, 400)\n        _dte = (event_dt.date() - datetime.now().date()).days\n        if RULES.get("pif_required_within_days", 0) and _dte <= RULES["pif_required_within_days"]:\n            data["payment_option"] = "pif"   # JC-ES-ENGAGE-1012: close-in weddings are paid in full'), ('LAZO_INVITE_DELAY_DAYS = 3 ', 'LAZO_INVITE_DELAY_DAYS = 8 '), ('    _send_lazo_invites(firestore.client(), datetime.now(timezone.utc))   # JC-LZ-INVITE-0928\n    db = firestore.client()', '    _send_lazo_invites(firestore.client(), datetime.now(timezone.utc))   # JC-LZ-INVITE-0928\n    try:\n        _send_milestones(firestore.client(), datetime.now(timezone.utc))   # JC-ES-ENGAGE-1012\n    except Exception as e:\n        print(f"milestone sweep failed: {e}")\n    db = firestore.client()')]
PKG_CANDIDATES = ['elizabethscott_packages.json', 'contract/elizabethscott_packages.json']
RULE_DAYS = 45

def rd(p): return io.open(p, encoding="utf-8").read()
def wr(p, s):
    shutil.copy(p, p + ".pre-engage1012.bak")
    io.open(p, "w", encoding="utf-8", newline="\n").write(s)

e = rd("lib/emails.py")
if "ENGAGE-1012" in e:
    print("lib/emails.py already patched")
else:
    wr("lib/emails.py", e.rstrip("\n") + "\n\n\n" + EMAILS_BLOCK)
    print("lib/emails.py: appended")

m = rd("main.py")
if "ENGAGE-1012" in m:
    print("main.py already patched")
else:
    lazo = "\n# ======================================================== lazo invite =="
    assert lazo in m, "lazo invite header not found in main.py"
    m = m.replace(lazo, "\n" + SWEEP_BLOCK + lazo.lstrip("\n"), 1)
    for old, new in EDITS:
        assert m.count(old) == 1, "expected exactly one match for: " + old[:70]
        m = m.replace(old, new, 1)
    wr("main.py", m)
    print("main.py: sweep + rule + lazo delay")

for pj in PKG_CANDIDATES:
    if os.path.exists(pj):
        d = json.load(io.open(pj, encoding="utf-8"))
        d["pricing_rules"]["pif_required_within_days"] = RULE_DAYS
        wr(pj, json.dumps(d, indent=2, ensure_ascii=False) + "\n")
        print(pj, ": pif_required_within_days =", RULE_DAYS)
        break
else:
    sys.exit("packages json not found: " + str(PKG_CANDIDATES))


# ---- JC-ES-NEXT-1012: what-happens-next timeline in the confirmation + optional wedding_website field ----
NEXT_EMAIL_EDITS = [('def welcome_email(api_key, booking, q_link=None):\n    first =', 'def welcome_email(api_key, booking, q_link=None):\n    # JC-ES-NEXT-1012: the confirmation carries the what-happens-next timeline\n    first ='), ('      <p>{money_line}</p>\n      <p><b>One thing we need from you:</b> your Wedding Day Questionnaire —\n      venues, timeline, key people, must-have shots. It takes about ten\n      minutes and helps us capture everything perfectly. Please complete it\n      at least two weeks before your date.</p>\n      QBTN_PLACEHOLDER\n      <p>If any details change afterward — venues, times, guest count — just\n      reopen the same link and update your answers.</p>', '      <p><b>What happens next.</b> We work in a few set milestones and we come\n      to you at each one, so you never need to chase us.</p>\n      <ol style="line-height:1.8;padding-left:20px">\n        <li><b>Now.</b> {money_line}</li>\n        <li><b>At your pace.</b> Your Wedding Day Questionnaire: venues, timeline,\n        key people, must-have shots. About ten minutes, and you can reopen the\n        same link to update it until two weeks before your date.</li>\n        <li><b>Every six weeks.</b> A short note from the studio with one question\n        that shapes how we film your day. Reply or ignore; both are fine.</li>\n        <li><b>Ten days out.</b> Final details: we send back everything we have and\n        ask you to confirm it in one reply.</li>\n        <li><b>Your wedding day.</b> We arrive at the time set in your questionnaire\n        and film the day as planned.</li>\n        <li><b>After.</b> Your film, delivered as set out in your agreement.</li>\n      </ol>\n      <p><b>The one thing we need from you</b> is the questionnaire.</p>\n      QBTN_PLACEHOLDER\n      <p>Questions at any point: reply to this email. It reaches the studio\n      directly and is answered by a person, usually the same day.</p>')]
NEXT_MAIN_EDITS = [('OPTIONAL_FIELDS = ["guest_count", "reception_venue", "start_time", "end_time"]', 'OPTIONAL_FIELDS = ["guest_count", "reception_venue", "start_time", "end_time",\n                   "wedding_website"]   # JC-ES-NEXT-1012: optional link so the studio can read up on the couple', 1), ('             f"Event: {booking[\'event_date\']} — "\n             f"{booking.get(\'ceremony_venue\',\'\')}",', '             f"Event: {booking[\'event_date\']} — "\n             f"{booking.get(\'ceremony_venue\',\'\')}",\n             f"Wedding website: {booking.get(\'wedding_website\') or \'not given\'}",', 2)]

e = rd("lib/emails.py")
if "NEXT-1012" in e:
    print("lib/emails.py: NEXT-1012 already patched")
else:
    for old, new in NEXT_EMAIL_EDITS:
        assert e.count(old) == 1, "NEXT-1012 emails: expected exactly one match for: " + old[:70]
        e = e.replace(old, new, 1)
    wr("lib/emails.py", e)
    print("lib/emails.py: NEXT-1012 welcome timeline")

m = rd("main.py")
if "NEXT-1012" in m:
    print("main.py: NEXT-1012 already patched")
else:
    for old, new, cnt in NEXT_MAIN_EDITS:
        assert m.count(old) == cnt, "NEXT-1012 main: expected %d match(es) for: %s" % (cnt, old[:70])
        m = m.replace(old, new)
    wr("main.py", m)
    print("main.py: NEXT-1012 wedding_website field + owner alert line")

for f in ("main.py", "lib/emails.py"):
    py_compile.compile(f, doraise=True)
print("COMPILED OK - now run the deploy line from the -command.txt file")
